mapper.insert:
INSERT INTO review_change_unit (
    snapshot_id, sequence_no, kind, risk_level, title, reason, decision_question,
    module_name, file_paths_json, key_hunks_json, requires_view, viewed_at,
    decision_status, decision_comment, decided_by, decided_at, created_at
) VALUES (
    #{snapshotId}, #{sequenceNo}, #{kind}, #{riskLevel}, #{title}, #{reason},
    #{decisionQuestion}, #{moduleName}, CAST(#{filePathsJson} AS JSON),
    CAST(#{keyHunksJson} AS JSON), #{requiresView}, #{viewedAt},
    #{decisionStatus}, #{decisionComment}, #{decidedBy}, #{decidedAt}, #{createdAt}
)

INSERT INTO review_finding (
    snapshot_id, change_unit_id, severity, status, title, description, impact,
    file_path, line_start, line_end, suggested_action, evidence_id, created_at, updated_at
) VALUES (
    #{snapshotId}, #{changeUnitId}, #{severity}, #{status}, #{title}, #{description},
    #{impact}, #{filePath}, #{lineStart}, #{lineEnd}, #{suggestedAction},
    #{evidenceId}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE review_finding
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.insert:
INSERT INTO review_evidence (
    snapshot_id, change_unit_id, evidence_type, status, title, command_text,
    summary, source_type, source_id, occurred_at, created_at
) VALUES (
    #{snapshotId}, #{changeUnitId}, #{evidenceType}, #{status}, #{title},
    #{commandText}, #{summary}, #{sourceType}, #{sourceId}, #{occurredAt}, #{createdAt}
)

mapper.update:
UPDATE review_evidence
SET status = #{status},
    summary = #{summary},
    occurred_at = #{occurredAt}
WHERE id = #{id}
